FIGURE_PDF_CROPS=[(137,'hyperbola265-unresolved-introduction',(35,175,714,280)),(137,'hyperbola265-unresolved-proof',(90,690,541,1050)),(137,'hyperbola266-unresolved-proof',(809,146,1197,490))]
def graph(n):
 vertical=n in [27,29];a=3;b=4;c=5;s=26
 def pt(x,y):return(250+s*x,190-s*y)
 paths=[path([pt(-8,0),pt(8,0)]),path([pt(0,-6),pt(0,6)])]
 for sign in [-1,1]:
  coords=[]
  for i in range(-120,121,2):
   t=i/100;x=sign*a*math.cosh(t);y=b*math.sinh(t);coords.append(pt(y,x) if vertical else pt(x,y))
  paths.append(path(coords))
 labels=[(462,196,'x'),(250,24,'y'),(256,212,'C(0,0)')]
 points=[]
 for val,letter in [(a,'V'),(c,'F')]:
  for sign in [-1,1]:x,y=(0,sign*val) if vertical else (sign*val,0);xx,yy=pt(x,y);points.append({'x':xx,'y':yy});labels.append((xx+5,yy-8,f'{letter}(0,{sign*val})' if vertical else f'{letter}({sign*val},0)'))
 if n in [25]:
  q=(a*math.cosh(.9),b*math.sinh(.9));qq=pt(*q);paths.extend([path([pt(-c,0),qq]),path([pt(c,0),qq])]);labels.append((qq[0]+6,qq[1]-8,'P(x,y)'));points.append({'x':qq[0],'y':qq[1]})
 if n in [28,29]:
  rect=[(-b,-a),(b,-a),(b,a),(-b,a),(-b,-a)] if vertical else [(-a,-b),(a,-b),(a,b),(-a,b),(-a,-b)]
  paths.append(path([pt(x,y) for x,y in rect],dash=True));m=a/b if vertical else b/a
  for sign in [-1,1]:paths.append(path([pt(-5,sign*m*-5),pt(5,sign*m*5)],dash=True))
  labels.extend([(335,51,'y=±(3/4)x' if vertical else 'y=±(4/3)x')])
 return geometry('Figure 9.'+str(n),'Figure 9.'+str(n)+' — '+('vertical' if vertical else 'horizontal')+' hyperbola with exact vertices and foci'+(' and asymptote rectangle' if n in [28,29] else ''),paths,labels,points=points,size=(530,405))
PAGES=[page('137_page_1.jpg',265,[heading('9.3 Hyperbola'),figure('hyperbola265-unresolved-introduction','Unresolved source introduction','The opening prose is motion-blurred in JPG, full/split PDFs; the Word transcription is garbled.'),heading('(i) Hyperbola and its center, foci, vertices, eccentricity, focal chord, transverse and conjugate axes, and latus recta'),paragraph('A hyperbola is the set of all points in the plane such that the difference of the distances from two fixed points (foci) to a point on the hyperbola has a constant magnitude.'),paragraph('The two fixed points F₁(−c,0) and F₂(c,0) are called the foci that lie on the x-axis at a distance c on each side of the origin. The hyperbola crosses the x-axis at V₁(−a,0),V₂(a,0), a distance a on each side of the origin, called vertices. The transverse and conjugate axes are the perpendicular axes with the x-axis containing the vertices and the y-axis containing the center.'),graph(24),paragraph('In order to obtain the magnitude of the difference of the distances from the two foci F₁(−c,0),F₂(c,0) to the vertex V₂(a,0), a>0:'),eq(r'd(F_1,V_2)-d(F_2,V_2)=(c+a)-(c-a)=2a'),paragraph('Here a is a nonnegative distance which is greater than zero, and the constant magnitude is 2a.'),heading('(ii) General form of the hyperbola'),paragraph('If P(x,y) is any point on the hyperbola, the distances from the two foci F₁(−c,0),F₂(c,0) to P are developed in the following source calculation.'),graph(25),figure('hyperbola265-unresolved-proof','Unresolved source derivation opening','Exact printed radical signs and intermediate labels cannot be certified from the blurred copies.'),note('This page remains source-partial. The preceding native figures illustrate the readable focus/vertex geometry with a=3,c=5; these numeric values are a learning model for the source symbolic labels. For a nondegenerate hyperbola, require c>a>0; the defining locus is |d(P,F₁)−d(P,F₂)|=2a. Without the absolute value, the signed difference describes only one branch. At a=0 the equal-distance locus is the perpendicular bisector, not a nondegenerate hyperbola.')]),
page('137_page_2.jpg',266,[figure('hyperbola266-unresolved-proof','Unresolved source squared derivation','Motion-blurred expansion at the top of printed 266; exact source algebra retained as a fragment, not silently reconstructed.'),note('Learning derivation, not a certified transcription of the blurred expansion: write d₁=√((x+c)²+y²), d₂=√((x−c)²+y²), and start on the branch d₁−d₂=2a. Squaring d₁=2a+d₂ gives cx−a²=a d₂. Squaring again gives c²x²−2a²cx+a⁴=a²[(x−c)²+y²], hence (c²−a²)x²−a²y²=a²(c²−a²). Set b²=c²−a²>0 to obtain x²/a²−y²/b²=1. The other branch has the opposite signed difference. Checking the original absolute-distance condition verifies the branches after squaring.'),heading('(iii) Standard form of the equation of Hyperbola'),paragraph('The standard form of the equation of a hyperbola with center at the origin and transverse axis along the x-axis is shown in Figure 9.26.'),eq(r'\frac{x^2}{a^2}-\frac{y^2}{b^2}=1','66'),graph(26),paragraph('If we replace the foci on the y-axis, center at the origin and pick any point P(x,y) on the plane, we develop the equation of the vertical hyperbola. Its transverse axis is along the y-axis, as shown in Figure 9.27.'),eq(r'\frac{y^2}{a^2}-\frac{x^2}{b^2}=1','67'),graph(27),heading('Graphing Standard Form Hyperbola'),paragraph('To sketch the standard-form hyperbola, determine center, vertices and foci. The transverse axis joins the vertices through the center. The conjugate axis is perpendicular to it through the center. The horizontal form has vertices (−a,0),(a,0) and conjugate-axis endpoints (0,±b).'),note('This page remains source-partial: the motion-blurred derivation and some graphing prose could not be resolved across JPG, full/split PDFs and Word. Standard equations (66),(67) are confirmed by the clearer continuation and examples on printed 267–268. The preceding prose is a readable reconstruction of the visible section content, without claiming exact missing words. The conjugate-axis endpoints are construction points and are not on the hyperbola.')]),
page('138_page_1.jpg',267,[paragraph('Why should we be concerned about the conjugate axis or length b? The significance of b is determined by solving the standard form for y:'),eq(r'\frac{x^2}{a^2}-\frac{y^2}{b^2}=1'),eq(r'-\frac{y^2}{b^2}=-\frac{x^2}{a^2}+1'),eq(r'y^2=b^2\left(\frac{x^2-a^2}{a^2}\right)=\frac{b^2}{a^2}(x^2-a^2)=\frac{b^2x^2}{a^2}\left(1-\frac{a^2}{x^2}\right)'),eq(r'y=\pm\frac{bx}{a}\sqrt{1-\frac{a^2}{x^2}}','68'),paragraph('Let us examine a²/x², with a constant. As larger values of x are substituted, the fraction becomes smaller and approaches zero. Thus for large x the term 1−a²/x² approaches 1 and y approaches the value ±(b/a)x. The hyperbola gets closer and closer to the lines:'),eq(r'y=\pm\frac b a x'),paragraph('These lines are called the asymptotes of the hyperbola. As x takes on values at greater distances from center, y becomes closer to the asymptotes without reaching their corresponding values. Since these lines are easy to graph, they are valuable aids in sketching.'),paragraph('For horizontal standard form x²/a²−y²/b²=1, the asymptotes are:'),eq(r'y=\pm\frac b a x','69'),paragraph('For vertical standard form x²/a²−y²/b²=1, the asymptotes are:'),eq(r'y=\pm\frac a b x','70'),heading('Asymptotes'),paragraph('If a straight line cuts a hyperbola in two points at an infinite distance from the origin and is itself at a finite distance from the origin, it is called the asymptotes. The orientation with C(0,0), vertices and foci is summarized:'),{'type':'dataTable','headers':['Orientation','Foci','Vertices'],'rows':[['Horizontal','F₁(−c,0),F₂(c,0)','V₁(−a,0),V₂(a,0)'],['Vertical','F₁(0,c),F₂(0,−c)','V₁(0,a),V₂(0,−a)']]},eq(r'c^2=a^2+b^2,\quad c>0'),note('The vertical-form sentence repeats the horizontal equation; its correct equation is y²/a²−x²/b²=1, with asymptotes y=±(a/b)x. More precisely, an asymptote is a line whose perpendicular distance from a curve tends to zero along a branch at infinity. There are no finite or literal Euclidean intersection points “at infinity”. In (68), √(x²)=|x|; the pair of ± branches permits the displayed x form, but a specified upper branch needs y=(b/a)|x|√(1−a²/x²). The difference from the corresponding line tends to zero, not just the ratio: |x|−√(x²−a²)=a²/(|x|+√(x²−a²))→0.')]),
page('138_page_2.jpg',268,[heading('Example 19'),paragraph('Sketch x²/9−y²/16=1, with center at the origin and transverse axis the x-axis. Determine vertices and foci.'),heading('Solution'),paragraph('The given equation is in horizontal standard form. Thus a²=9,a=±3 and b²=16,b=±4. Vertices V₁(−3,0),V₂(3,0). Find c for foci:'),eq(r'c^2=a^2+b^2=9+16=25,\quad c=\pm5'),paragraph('Foci are F₁(−5,0),F₂(5,0). Asymptotes:'),eq(r'y=\frac b a x=\frac43x,\quad y=-\frac b a x=-\frac43x'),paragraph('Locate conjugate-axis endpoints (0,−4),(0,4), draw lines through them parallel to the x-axis and lines through vertices parallel to y. This completes the rectangle; its extended diagonals are the asymptotes. The sketch is Figure 9.28.'),graph(28),heading('Example 20'),paragraph('Sketch 16y²−9x²=144, with center at the origin and transverse axis the y-axis. Determine vertices and foci.'),heading('Solution'),eq(r'16y^2-9x^2=144\quad\Rightarrow\quad\frac{16y^2}{144}-\frac{9x^2}{144}=1\quad\Rightarrow\quad\frac{y^2}{9}-\frac{x^2}{16}=1','71'),paragraph('Select a²=9,a=±3 and b²=16,b=±4. Vertices (0,3),(0,−3); conjugate-axis endpoints (−4,0),(4,0). Find c:'),eq(r'c^2=a^2+b^2=9+16=25,\quad c=\pm5'),paragraph('Foci are (0,5),(0,−5); asymptotes:'),eq(r'y=\frac a b x=\frac34x,\quad y=-\frac a b x=-\frac34x'),paragraph('Sketch the rectangle formed by points (0,±3),(±4,0), then its diagonal asymptotes. With asymptotes, vertices and foci, sketch the hyperbola as in Figure 9.29.'),graph(29),note('The positive lengths are a=3,b=4,c=5. The ± signs denote coordinates of opposite vertices, foci and construction endpoints, rather than negative lengths. The rectangle corners are (±3,±4) for Example 19 and (±4,±3) for Example 20; the four stated axis points are its side midpoints.')])]
